CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE jurisdictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, boundary geometry(MultiPolygon,4326) NOT NULL);
CREATE INDEX jurisdictions_geo ON jurisdictions USING gist(boundary);
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE roles(name text PRIMARY KEY);
INSERT INTO roles VALUES ('CITIZEN'),('AUTHORITY'),('RESCUER'),('ADMIN');
CREATE TABLE permissions(name text PRIMARY KEY);
INSERT INTO permissions VALUES ('DISPATCH'),('ANNOUNCE'),('MANAGE_USERS'),('MANAGE_TEAMS'),('CONFIGURE');
CREATE TABLE user_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cognito_sub text NOT NULL UNIQUE, email text NOT NULL UNIQUE, name text NOT NULL, role text NOT NULL REFERENCES roles(name), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','INACTIVE')), department_id uuid REFERENCES departments, jurisdiction_id uuid REFERENCES jurisdictions, supervisor_id uuid REFERENCES user_profiles, phone text, sms_enabled boolean NOT NULL DEFAULT false, session_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CHECK(role<>'AUTHORITY' OR (department_id IS NOT NULL AND jurisdiction_id IS NOT NULL)));
CREATE TABLE user_permissions(user_id uuid REFERENCES user_profiles ON DELETE CASCADE,permission text REFERENCES permissions,PRIMARY KEY(user_id,permission));
CREATE TABLE sessions(id_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES user_profiles, csrf text NOT NULL, version integer NOT NULL, refresh_cipher text, access_expires timestamptz NOT NULL, expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states(id_hash text PRIMARY KEY, verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE rescue_teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,organization_id uuid REFERENCES organizations, department_id uuid NOT NULL REFERENCES departments,jurisdiction_id uuid NOT NULL REFERENCES jurisdictions,availability text NOT NULL DEFAULT 'OFF_DUTY' CHECK(availability IN('AVAILABLE','OFF_DUTY','UNAVAILABLE')), capacity integer NOT NULL DEFAULT 1 CHECK(capacity BETWEEN 1 AND 5),vehicle text, location geography(Point,4326),location_at timestamptz,accuracy double precision,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX rescue_teams_geo ON rescue_teams USING gist(location);
CREATE TABLE team_memberships(team_id uuid REFERENCES rescue_teams,user_id uuid UNIQUE REFERENCES user_profiles,PRIMARY KEY(team_id,user_id));
CREATE TABLE team_capabilities(team_id uuid REFERENCES rescue_teams,capability text NOT NULL,expires_at timestamptz,PRIMARY KEY(team_id,capability));
CREATE TABLE categories(code text PRIMARY KEY,label text NOT NULL,sensitive boolean NOT NULL DEFAULT false,required_capabilities text[] NOT NULL DEFAULT '{}');
CREATE TABLE category_departments(category text REFERENCES categories,department_id uuid REFERENCES departments,PRIMARY KEY(category,department_id));
CREATE TABLE escalation_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,radii_m integer[] NOT NULL DEFAULT '{5000,10000,25000}',delays_seconds integer[] NOT NULL DEFAULT '{0,60,180}',active boolean NOT NULL DEFAULT true,CHECK(array_length(radii_m,1)=array_length(delays_seconds,1)));
CREATE TABLE incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES user_profiles,category text NOT NULL REFERENCES categories,severity text NOT NULL CHECK(severity IN('LOW','MODERATE','HIGH','CRITICAL')),kind text NOT NULL CHECK(kind IN('EMERGENCY','REPORT')),description text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',location geography(Point,4326) NOT NULL,status text NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN('SUBMITTED','NEEDS_VERIFICATION','ACKNOWLEDGED','DISPATCHED','TEAM_EN_ROUTE','TEAM_ON_SCENE','RESOLVED','DUPLICATE','CANCELLED','UNABLE_TO_RESPOND','REOPENED')), escalation_state text NOT NULL DEFAULT 'PENDING',published boolean NOT NULL DEFAULT false,owner_id uuid REFERENCES user_profiles,policy_id uuid REFERENCES escalation_policies,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX incidents_geo ON incidents USING gist(location);
CREATE INDEX incidents_reporter ON incidents(reporter_id,created_at DESC);
CREATE TABLE incident_departments(incident_id uuid REFERENCES incidents,department_id uuid REFERENCES departments,PRIMARY KEY(incident_id,department_id));
CREATE TABLE incident_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES incidents,team_id uuid NOT NULL REFERENCES rescue_teams,status text NOT NULL DEFAULT 'OFFERED' CHECK(status IN('OFFERED','ACCEPTED','DISPATCHED','EN_ROUTE','ARRIVED','IN_PROGRESS','COMPLETED','DECLINED','CANCELLED')),created_by uuid REFERENCES user_profiles,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX active_assignment_unique ON incident_assignments(incident_id,team_id) WHERE status NOT IN('COMPLETED','DECLINED','CANCELLED');
CREATE INDEX assignments_team ON incident_assignments(team_id,status);
CREATE TABLE incident_status_history(id bigserial PRIMARY KEY,incident_id uuid NOT NULL REFERENCES incidents,actor_id uuid REFERENCES user_profiles,from_status text,to_status text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY,actor_id uuid REFERENCES user_profiles,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION deny_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON incident_status_history FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
CREATE TABLE location_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),team_id uuid NOT NULL REFERENCES rescue_teams,user_id uuid NOT NULL REFERENCES user_profiles,active boolean NOT NULL DEFAULT true,started_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '12 hours',stopped_at timestamptz);
CREATE UNIQUE INDEX active_location_device ON location_sessions(team_id) WHERE active;
CREATE TABLE team_location_updates(id bigserial PRIMARY KEY,session_id uuid NOT NULL REFERENCES location_sessions,team_id uuid NOT NULL REFERENCES rescue_teams,location geography(Point,4326) NOT NULL,accuracy double precision NOT NULL CHECK(accuracy>=0),observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX location_retention ON team_location_updates(received_at);
CREATE TABLE route_cache(assignment_id uuid PRIMARY KEY REFERENCES incident_assignments,distance_m double precision NOT NULL,duration_s double precision NOT NULL,calculated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE incident_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES incidents,owner_id uuid NOT NULL REFERENCES user_profiles,object_key text UNIQUE NOT NULL,content_type text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 5242880),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','AVAILABLE','REJECTED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,type text NOT NULL,department_id uuid NOT NULL REFERENCES departments,team_id uuid REFERENCES rescue_teams,quantity integer NOT NULL CHECK(quantity>=0),status text NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','MAINTENANCE','UNAVAILABLE')));
CREATE TABLE resource_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),resource_id uuid NOT NULL REFERENCES resources,incident_id uuid NOT NULL REFERENCES incidents,quantity integer NOT NULL CHECK(quantity>0),released_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES user_profiles,department_id uuid REFERENCES departments,jurisdiction_id uuid REFERENCES jurisdictions,title text NOT NULL,body text NOT NULL,audience text NOT NULL CHECK(audience IN('EVERYONE','AUTHORITIES_ONLY')),importance text NOT NULL CHECK(importance IN('URGENT','IMPORTANT','INFORMATION')),expires_at timestamptz NOT NULL,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcement_revisions(id bigserial PRIMARY KEY,announcement_id uuid NOT NULL REFERENCES announcements,actor_id uuid NOT NULL REFERENCES user_profiles,title text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid REFERENCES incidents,recipient_id uuid NOT NULL REFERENCES user_profiles,channel text NOT NULL CHECK(channel IN('IN_APP','SMS')),dedupe_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','AVAILABLE','SUBMITTED','DELIVERED','FAILED','UNKNOWN')),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES notification_jobs,provider_id text,outcome text NOT NULL,error_code text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,payload jsonb NOT NULL,dedupe_key text NOT NULL UNIQUE,published_at timestamptz,attempts integer NOT NULL DEFAULT 0,next_attempt timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox_events(next_attempt) WHERE published_at IS NULL;
CREATE TABLE processed_events(id uuid PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE escalation_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES incidents,stage integer NOT NULL,due_at timestamptz NOT NULL,completed_at timestamptz,outcome text,UNIQUE(incident_id,stage));
CREATE INDEX escalation_due ON escalation_executions(due_at) WHERE completed_at IS NULL;
CREATE TABLE idempotency_keys(actor_id uuid REFERENCES user_profiles,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,key));
CREATE TABLE analytics_exports(day date PRIMARY KEY,object_key text NOT NULL,exported_at timestamptz NOT NULL DEFAULT now());
